            @classmethod
            @custom_decorator
            def die(cls, when, *args, **kwargs):
                pass

    assert 'HumanSoul.die(cls, when, args, kwargs) mismatches ' \
           'HumanSoulInterface.die() member access modifier.' == error.value.message

